{
  "findings": [
    {
      "check_id": "CKV_AWS_111",
      "title": "IAM user without MFA enabled",
      "resource": "aws_iam_user.fp3-deny-iam-user",
      "severity": "HIGH",
      "explanation": "IAM users should have MFA enabled to enhance account security and prevent unauthorized access."
    }
  ],
  "patched_code": "resource "aws_iam_user" "fp3-deny-iam-user" {
  name = "fp3-deny-iam-user"
  path = "/"
}

resource "aws_iam_user_policy" "fp3-deny-iam-user-mfa" {
  name = "require-mfa"
  user = aws_iam_user.fp3-deny-iam-user.name

  policy = <<EOT
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Deny",
      "Action": "*",
      "Resource": "*",
      "Condition": {
        "BoolIfExists": {
          "aws:MultiFactorAuthPresent": "false"
        }
      }
    }
  ]
}
EOT
}
",
  "fix_summary": "Added an IAM user policy to enforce MFA for the IAM user, ensuring enhanced security by denying actions if MFA is not enabled."
}
